static int cmp(const void *a, const void *b) {
  int *x = *(int **)a;
  int *y = *(int **)b;
  return x[0] - y[0];
}

int **merge(int **intervals, int intervalsSize, int *intervalsColSize, int *returnSize, int **returnColumnSizes) {
  *returnSize = 0;
  if (intervalsSize == 0) {
    *returnColumnSizes = NULL;
    return NULL;
  }
  qsort(intervals, intervalsSize, sizeof(int *), cmp);
  int **merged = (int **)malloc(sizeof(int *) * intervalsSize);
  *returnColumnSizes = (int *)malloc(sizeof(int) * intervalsSize);
  for (int i = 0; i < intervalsSize; i++) {
    int L = intervals[i][0], R = intervals[i][1];
    if (*returnSize == 0 || merged[*returnSize - 1][1] < L) {
      merged[*returnSize] = (int *)malloc(sizeof(int) * 2);
      merged[*returnSize][0] = L;
      merged[*returnSize][1] = R;
      (*returnColumnSizes)[*returnSize] = 2;
      (*returnSize)++;
    } else if (R > merged[*returnSize - 1][1]) {
      merged[*returnSize - 1][1] = R;
    }
  }
  return merged;
}

func merge(intervals [][]int) [][]int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][0] < intervals[j][0] })
	res := [][]int{}
	for _, iv := range intervals {
		if len(res) == 0 || res[len(res)-1][1] < iv[0] {
			res = append(res, []int{iv[0], iv[1]})
		} else if iv[1] > res[len(res)-1][1] {
			res[len(res)-1][1] = iv[1]
		}
	}
	return res
}

class Solution {
  public int[][] merge(int[][] intervals) {
    if (intervals.length == 0) {
      return new int[0][];
    }
    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
    List<int[]> merged = new ArrayList<>();
    for (int[] iv : intervals) {
      if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < iv[0]) {
        merged.add(new int[] { iv[0], iv[1] });
      } else {
        merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
      }
    }
    return merged.toArray(new int[merged.size()][]);
  }
}

class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        intervals.sort(key=lambda x: x[0])
        res = []
        for L, R in intervals:
            if not res or res[-1][1] < L:
                res.append([L, R])
            elif R > res[-1][1]:
                res[-1][1] = R
        return res

impl Solution {
  pub fn merge(mut intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    intervals.sort_by_key(|v| v[0]);
    let mut res: Vec<Vec<i32>> = vec![];
    for iv in intervals {
      match res.last_mut() {
        Some(last) if last[1] >= iv[0] => {
          last[1] = last[1].max(iv[1]);
        }
        _ => res.push(vec![iv[0], iv[1]]),
      }
    }
    res
  }
}

const merge = (intervals: number[][]): number[][] => {
  intervals.sort((a, b) => a[0] - b[0]);
  const res: number[][] = [];
  for (const [L, R] of intervals) {
    if (res.length === 0 || res[res.length - 1][1] < L) {
      res.push([L, R]);
    } else if (R > res[res.length - 1][1]) {
      res[res.length - 1][1] = R;
    }
  }
  return res;
};

class Solution {
public:
  vector<vector<int>> merge(vector<vector<int>> &intervals) {
    if (intervals.size() == 0) {
      return {};
    }
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> merged;
    for (int i = 0; i < intervals.size(); ++i) {
      int L = intervals[i][0], R = intervals[i][1];
      if (!merged.size() || merged.back()[1] < L) {
        merged.push_back({L, R});
      } else {
        merged.back()[1] = max(merged.back()[1], R);
      }
    }
    return merged;
  }
};
